WITH SCIDS AS ( SELECT SCENE_NODE_ID,NODE_VALUE,BOOKSET_ID FROM BOK_SCENECONFIG WHERE BOOKSET_ID = #{booksetId} AND NODE_ID = #{ACCOUNTEVENTS}
AND NODE_VALUE
#{item}
) SELECT BOK_SCENESUBJECT.SCENE_NODE_ID "sceneNodeId", BOK_SCENESUBJECT.SUBJECT_NO "subjectId", BOK_SCENESUBJECT.CD_FLAG "cdFlag", BOK_TABLEDICT.DICT_CODE "formElement", BOK_SCENESUBJECT.ACCOUNT_NET "accountNet", BOK_SUBJECT.SUBJECT_NAME subjectName, BOK_SUBJECT.FSUBJECT_ID fsubjectId, BOK_SUBJECT.BASE_SUBJECT_NATURE "baseSubjectNature", BOK_SUBJECT.SUBJECT_TYPE "subjectType", BOK_SUBJECT.ACC_QUA_FLAG "accQuaFlag", BOK_SUBJECT.ACC_INT_FLAG "accIntFlag", BOK_SUBJECT.OVERDRAWN_FLAG "overdrawnFlag", BOK_SUBJECT.GEN_DETSUB_FLAG "genDetsubFlag", BOK_SUBJECT.BAL_FLAG "balFlag", SCIDS.NODE_VALUE "nodeValue", BOK_SCENESUBJECT.BOK_DETAIL_ID "bokDetailId", BOK_SCENESUBJECT.BOOKSET_ID booksetId FROM BOK_SCENESUBJECT BOK_SCENESUBJECT INNER JOIN SCIDS ON SCIDS.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND INSTR(BOK_SCENESUBJECT.SCENE_NODE_ID, SCIDS.SCENE_NODE_ID) = 1 LEFT JOIN BOK_SUBJECT BOK_SUBJECT ON BOK_SUBJECT.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND BOK_SCENESUBJECT.SUBJECT_NO = BOK_SUBJECT.SUBJECT_NO LEFT JOIN BOK_TABLEDICT BOK_TABLEDICT ON BOK_TABLEDICT.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND BOK_TABLEDICT.DICT_ID = BOK_SCENESUBJECT.FORM_ELE WHERE BOK_SCENESUBJECT.BOOKSET_ID = #{booksetId} ORDER BY BOK_SCENESUBJECT.SCENE_NODE_ID

WITH SCIDS AS ( SELECT SCENE_NODE_ID,BOOKSET_ID FROM BOK_SCENECONFIG WHERE BOOKSET_ID = #{booksetId} AND NODE_ID = #{ACCOUNTEVENTS}
AND NODE_VALUE
#{item}
) SELECT BOK_SCENECONFIG.SCENE_NODE_ID "sceneNodeId", BOK_SCENECONFIG.FSCENE_NODEID "fSceneNodeId", BOK_SCENECONFIG.BOOKSET_ID "booksetId", NVL(BOK_TABLEDICT.DICT_CODE, BOK_SCENECONFIG.NODE_ID) "nodeId", BOK_SCENECONFIG.NODE_VALUE "nodeValue" FROM BOK_SCENECONFIG BOK_SCENECONFIG INNER JOIN SCIDS ON SCIDS.BOOKSET_ID = BOK_SCENECONFIG.BOOKSET_ID AND INSTR(BOK_SCENECONFIG.SCENE_NODE_ID, SCIDS.SCENE_NODE_ID) = 1 LEFT JOIN BOK_TABLEDICT BOK_TABLEDICT ON BOK_TABLEDICT.BOOKSET_ID = BOK_SCENECONFIG.BOOKSET_ID AND BOK_TABLEDICT.DICT_ID = BOK_SCENECONFIG.NODE_ID WHERE BOK_SCENECONFIG.BOOKSET_ID = #{booksetId} ORDER BY BOK_SCENECONFIG.SCENE_NODE_ID

SELECT MATCH_TYPE, SOURCE, TARGET
FROM BOK_MATCH_RLAT
WHERE 1 = 1

AND MATCH_TYPE

    #{item}



AND SOURCE = #{source} 


AND ACCT_STANDARD = #{acctStandard}

		SELECT 
			SEQ_NO AS seqNo,
			BOOKSET_ID AS booksetId,
			HAPPEN_DATE AS happenDate,
			TASK_ID AS taskId,
			BOOKSET_DATE AS booksetDate,
			BOK_DETAIL_ID AS bokDetailId,
			BOOK_DATE AS bookDate,
			IS_BACK_VALUE AS isBackValue
		FROM BOK_BATCH_TASK_TODO
		WHERE 
            SEQ_NO = #{seqNo}

                AND TASK_ID = #{taskId}


                 AND BOOKSET_DATE = #{BOOKSET_DATE}


                 AND BOOK_DATE = #{BOOK_DATE}


                 AND HAPPEN_DATE = #{HAPPEN_DATE}

            AND IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
        ORDER BY 
            TASK_ID,BOOKSET_DATE,BOOK_DATE,HAPPEN_DATE

SELECT 
    ACCT_STANDARD,BUSI_TYPE,PS,PS_ORDER
FROM BOK_TRADE_ORDER
WHERE ACCT_STANDARD = #{acctStandard,jdbcType=VARCHAR}
  AND BUSI_TYPE = #{busiType,jdbcType=VARCHAR}

  AND PS = #{ps,jdbcType=VARCHAR}

ORDER BY PS_ORDER

        SELECT 
            *
        FROM BOK_BOOKSET
        WHERE
            1 = 1

                AND bookset_id IN

